 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying||!s.path.EndsWith("Level_1F_Factory.unity"))throw new Exception("Saved 1F required");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);string e="Assets/Afrer_Seconds/05.Model/Environment/1F/",p=e+"F1_Wayfinding.fbx";var mi=(ModelImporter)AssetImporter.GetAtPath(p);mi.importAnimation=false;mi.animationType=ModelImporterAnimationType.None;mi.isReadable=false;mi.importNormals=ModelImporterNormals.Import;mi.materialImportMode=ModelImporterMaterialImportMode.ImportStandard;mi.materialLocation=ModelImporterMaterialLocation.InPrefab;foreach(string n in new[]{"Dark","Paper"})mi.AddRemap(new AssetImporter.SourceAssetIdentifier(typeof(Material),"F1M_"+n),AssetDatabase.LoadAssetAtPath<Material>(e+"Materials/F1M_"+n+".mat"));mi.SaveAndReimport();var root=GameObject.Find("1F_AbandonedFactory");if(!root.transform.Find("F1_Wayfinding")){var g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>(p),root.transform);g.name="F1_Wayfinding";}EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(s);return new{signs=4};}
